-- Seeds the built-in email templates.
--
-- These were previously created by EmailTemplateController only when the
-- table was missing. schema.sql creates the table at install, so that
-- branch never ran and stores shipped with no templates at all.
--
-- ON DUPLICATE KEY leaves existing rows alone, so a template a shopkeeper
-- has already edited is never overwritten by an update.

INSERT INTO wk_email_templates (slug, name, subject, body, is_active) VALUES
('welcome', 'Welcome Email', 'Welcome to {{store_name}}', '<div style="text-align:center;margin-bottom:28px"><div style="font-size:52px;margin-bottom:8px">&#128075;</div><h1 style="font-size:27px;font-weight:900;margin:0 0 6px;color:#1e1b2e">Welcome, {{customer_name}}</h1><p style="color:#6b7280;margin:0;font-size:15px">Your account at {{store_name}} is ready</p></div><p style="font-size:14px;line-height:1.75;color:#1e1b2e;margin:0 0 18px">You can now check out faster, keep your addresses saved, and follow your orders from one place.</p><div style="background:#faf8f6;border-radius:10px;padding:20px;margin-bottom:24px"><table style="width:100%;font-size:14px"><tr><td style="color:#6b7280;padding:6px 0">Your account email</td><td style="text-align:right;font-weight:800">{{customer_email}}</td></tr></table></div><div style="text-align:center;margin-top:28px"><a href="{{store_url}}" style="display:inline-block;background:linear-gradient(135deg,#8b5cf6,#ec4899);color:#fff;padding:15px 34px;border-radius:10px;text-decoration:none;font-weight:800;font-size:15px">Start shopping</a></div>', 1),
('order-confirmation', 'Order Confirmation', 'Order confirmed - {{order_number}}', '<div style="text-align:center;margin-bottom:28px"><div style="font-size:52px;margin-bottom:8px">&#127881;</div><h1 style="font-size:27px;font-weight:900;margin:0 0 6px;color:#1e1b2e">Order confirmed</h1><p style="color:#6b7280;margin:0;font-size:15px">Thank you for your order, {{customer_name}}</p></div><div style="background:#faf8f6;border-radius:10px;padding:20px;margin-bottom:24px"><table style="width:100%;font-size:14px"><tr><td style="color:#6b7280;padding:6px 0">Order number</td><td style="text-align:right;font-weight:800">{{order_number}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Date</td><td style="text-align:right;font-weight:700">{{order_date}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Payment</td><td style="text-align:right;font-weight:700">{{payment_method}}</td></tr></table></div><h2 style="font-size:16px;font-weight:800;margin:0 0 10px">Items ordered</h2>{{order_items_html}}<div style="background:#faf8f6;border-radius:10px;padding:20px;margin-bottom:24px"><table style="width:100%;font-size:14px"><tr><td style="color:#6b7280;padding:6px 0">Subtotal</td><td style="text-align:right;font-weight:700">{{order_subtotal}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Tax</td><td style="text-align:right;font-weight:700">{{order_tax}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Shipping</td><td style="text-align:right;font-weight:700">{{order_shipping}}</td></tr><tr><td style="padding:14px 0 0;border-top:2px solid #1e1b2e;font-size:20px;font-weight:900">Total</td><td style="text-align:right;padding:14px 0 0;border-top:2px solid #1e1b2e;font-size:20px;font-weight:900;font-family:monospace">{{order_total}}</td></tr></table></div><div style="display:flex;gap:24px;margin-top:26px;padding-top:22px;border-top:1px solid #e8e5df"><div style="flex:1"><div style="font-size:11px;font-weight:800;text-transform:uppercase;color:#6b7280;margin-bottom:6px">Shipping address</div><div style="font-size:14px;line-height:1.7">{{shipping_address}}</div></div><div style="flex:1"><div style="font-size:11px;font-weight:800;text-transform:uppercase;color:#6b7280;margin-bottom:6px">Billing address</div><div style="font-size:14px;line-height:1.7">{{billing_address}}</div></div></div><div style="text-align:center;margin-top:28px"><a href="{{store_url}}" style="display:inline-block;background:linear-gradient(135deg,#8b5cf6,#ec4899);color:#fff;padding:15px 34px;border-radius:10px;text-decoration:none;font-weight:800;font-size:15px">View your order</a></div>', 1),
('order-pending', 'Order Awaiting Payment', 'Payment pending - {{order_number}}', '<div style="text-align:center;margin-bottom:28px"><div style="font-size:52px;margin-bottom:8px">&#8987;</div><h1 style="font-size:27px;font-weight:900;margin:0 0 6px;color:#1e1b2e">We are waiting on your payment</h1><p style="color:#6b7280;margin:0;font-size:15px">Order {{order_number}} is reserved for now</p></div><p style="font-size:14px;line-height:1.75;color:#1e1b2e;margin:0 0 18px">Your items are held while the payment goes through. If you closed the payment window before it finished, you can pick up where you left off using the button below.</p><div style="background:#faf8f6;border-radius:10px;padding:20px;margin-bottom:24px"><table style="width:100%;font-size:14px"><tr><td style="color:#6b7280;padding:6px 0">Order number</td><td style="text-align:right;font-weight:800">{{order_number}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Amount due</td><td style="text-align:right;font-weight:800">{{order_total}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Placed</td><td style="text-align:right;font-weight:700">{{order_date}}</td></tr></table></div><div style="text-align:center;margin-top:28px"><a href="{{order_url}}" style="display:inline-block;background:linear-gradient(135deg,#8b5cf6,#ec4899);color:#fff;padding:15px 34px;border-radius:10px;text-decoration:none;font-weight:800;font-size:15px">Complete your payment</a></div><p style="font-size:14px;line-height:1.75;color:#6b7280;margin:0 0 18px">If the payment is not completed, the order is released and the items go back into stock.</p>', 1),
('order-cancelled', 'Order Cancelled', 'Order cancelled - {{order_number}}', '<div style="text-align:center;margin-bottom:28px"><div style="font-size:52px;margin-bottom:8px">&#10060;</div><h1 style="font-size:27px;font-weight:900;margin:0 0 6px;color:#1e1b2e">Your order has been cancelled</h1><p style="color:#6b7280;margin:0;font-size:15px">Order {{order_number}}</p></div><p style="font-size:14px;line-height:1.75;color:#1e1b2e;margin:0 0 18px">This order has been cancelled and nothing further will be sent. Any items held for it have gone back into stock.</p><div style="background:#faf8f6;border-radius:10px;padding:20px;margin-bottom:24px"><table style="width:100%;font-size:14px"><tr><td style="color:#6b7280;padding:6px 0">Order number</td><td style="text-align:right;font-weight:800">{{order_number}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Order total</td><td style="text-align:right;font-weight:800">{{order_total}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Cancelled</td><td style="text-align:right;font-weight:700">{{cancelled_date}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Reason</td><td style="text-align:right;font-weight:700">{{cancel_reason}}</td></tr></table></div><p style="font-size:14px;line-height:1.75;color:#6b7280;margin:0 0 18px">If you had already paid, the money is being returned to your original payment method and you will get a separate email with the refund reference.</p><div style="text-align:center;margin-top:28px"><a href="{{store_url}}" style="display:inline-block;background:linear-gradient(135deg,#8b5cf6,#ec4899);color:#fff;padding:15px 34px;border-radius:10px;text-decoration:none;font-weight:800;font-size:15px">Back to the store</a></div>', 1),
('payment-receipt', 'Payment Receipt', 'Payment receipt - {{order_number}}', '<div style="text-align:center;margin-bottom:28px"><div style="font-size:52px;margin-bottom:8px">&#129534;</div><h1 style="font-size:27px;font-weight:900;margin:0 0 6px;color:#1e1b2e">Payment received</h1><p style="color:#6b7280;margin:0;font-size:15px">Receipt for order {{order_number}}</p></div><div style="background:#faf8f6;border-radius:10px;padding:20px;margin-bottom:24px"><table style="width:100%;font-size:14px"><tr><td style="color:#6b7280;padding:6px 0">Amount paid</td><td style="text-align:right;font-weight:900">{{amount_paid}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Paid on</td><td style="text-align:right;font-weight:700">{{payment_date}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Payment method</td><td style="text-align:right;font-weight:700">{{payment_method}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Transaction ID</td><td style="text-align:right;font-weight:800">{{transaction_id}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Order number</td><td style="text-align:right;font-weight:800">{{order_number}}</td></tr></table></div><p style="font-size:14px;line-height:1.75;color:#6b7280;margin:0 0 18px">Keep this email as your receipt. Quote the transaction ID above if you need to ask us anything about this payment.</p><div style="text-align:center;margin-top:28px"><a href="{{invoice_url}}" style="display:inline-block;background:linear-gradient(135deg,#8b5cf6,#ec4899);color:#fff;padding:15px 34px;border-radius:10px;text-decoration:none;font-weight:800;font-size:15px">Download invoice</a></div>', 1),
('refund-notification', 'Refund Notification', 'Refund issued - {{order_number}}', '<div style="text-align:center;margin-bottom:28px"><div style="font-size:52px;margin-bottom:8px">&#128184;</div><h1 style="font-size:27px;font-weight:900;margin:0 0 6px;color:#1e1b2e">Your refund has been issued</h1><p style="color:#6b7280;margin:0;font-size:15px">Order {{order_number}}</p></div><div style="background:#faf8f6;border-radius:10px;padding:20px;margin-bottom:24px"><table style="width:100%;font-size:14px"><tr><td style="color:#6b7280;padding:6px 0">Refund amount</td><td style="text-align:right;font-weight:900">{{refund_amount}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Refund ID</td><td style="text-align:right;font-weight:800">{{refund_id}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Date</td><td style="text-align:right;font-weight:700">{{refund_date}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Time</td><td style="text-align:right;font-weight:700">{{refund_time}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Refunded to</td><td style="text-align:right;font-weight:700">{{refund_method}}</td></tr></table></div><p style="font-size:14px;line-height:1.75;color:#1e1b2e;margin:0 0 18px">It usually appears on your statement within 5 to 10 working days, depending on your bank. Quote refund ID <strong>{{refund_id}}</strong> if you need to ask us about it.</p><p style="font-size:14px;line-height:1.75;color:#6b7280;margin:0 0 18px">Thank you for shopping with {{store_name}}.</p>', 1),
('shipping-notification', 'Shipping Notification', 'Your order has shipped - {{order_number}}', '<div style="text-align:center;margin-bottom:28px"><div style="font-size:52px;margin-bottom:8px">&#128230;</div><h1 style="font-size:27px;font-weight:900;margin:0 0 6px;color:#1e1b2e">Your order is on its way</h1><p style="color:#6b7280;margin:0;font-size:15px">Order {{order_number}}</p></div><div style="background:#faf8f6;border-radius:10px;padding:20px;margin-bottom:24px"><table style="width:100%;font-size:14px"><tr><td style="color:#6b7280;padding:6px 0">Carrier</td><td style="text-align:right;font-weight:800">{{carrier_name}}</td></tr><tr><td style="color:#6b7280;padding:6px 0">Tracking number</td><td style="text-align:right;font-weight:800">{{tracking_number}}</td></tr></table></div><div style="text-align:center;margin-top:28px"><a href="{{tracking_url}}" style="display:inline-block;background:linear-gradient(135deg,#8b5cf6,#ec4899);color:#fff;padding:15px 34px;border-radius:10px;text-decoration:none;font-weight:800;font-size:15px">Track your parcel</a></div><p style="font-size:14px;line-height:1.75;color:#6b7280;margin:0 0 18px">Tracking can take a few hours to start updating after the carrier collects the parcel.</p>', 1)
ON DUPLICATE KEY UPDATE slug = slug;
